def preserve_progress(apps, schema_editor):
    alias = schema_editor.connection.alias
    Phase = apps.get_model('fellows', 'Phase')
    Cohort = apps.get_model('fellows', 'Cohort')
    for order, name in enumerate(['Orbit of Ideas', 'Launch Sequence', 'Mission Build', 'Trajectory', 'Touchdown']):
        Phase.objects.using(alias).get_or_create(name=name, defaults={'order': order})
    for cohort in Cohort.objects.using(alias).all():
        name = cohort.current_phase.strip()
        if name:
            phase, _ = Phase.objects.using(alias).get_or_create(name=name, defaults={'order': 100})
            cohort.phase_id = phase.pk
            cohort.save(using=alias, update_fields=['phase'])
    Badge = apps.get_model('fellows', 'Badge')
    for name in Badge.objects.using(alias).exclude(required_phase='').values_list('required_phase', flat=True).distinct():
        Phase.objects.using(alias).get_or_create(name=name, defaults={'order': 100})
    Submission = apps.get_model('fellows', 'AvailabilitySubmission')
    Task = apps.get_model('fellows', 'Task')
    Slots = apps.get_model('fellows', 'MeetingAvailability')
    for task in Task.objects.using(alias).filter(status='complete', availability_request__isnull=False, assigned_to__isnull=False):
        if Slots.objects.using(alias).filter(availability_request_id=task.availability_request_id, fellow_id=task.assigned_to_id).exists():
            Submission.objects.using(alias).get_or_create(availability_request_id=task.availability_request_id, fellow_id=task.assigned_to_id)


def restore_phase_text(apps, schema_editor):
    for cohort in apps.get_model('fellows', 'Cohort').objects.using(schema_editor.connection.alias).select_related('phase'):
        cohort.current_phase = cohort.phase.name if cohort.phase else ''
        cohort.save(using=schema_editor.connection.alias, update_fields=['current_phase'])


